mapper.update:
UPDATE audit_archive_online_purge_receipt
SET recovery_version=#{version},recovery_sha256=#{sha256},recovery_bytes=#{byteCount}
WHERE batch_id=#{batchId} AND recovery_version IS NULL

mapper.select:
SELECT id FROM audit_operation_attempt WHERE id IN
#{id}
ORDER BY id FOR UPDATE

SELECT EXISTS(
  SELECT 1 FROM audit_archive_member m JOIN audit_attempt_outcome o ON o.attempt_id=m.attempt_id WHERE m.batch_id=#{id}
  UNION ALL
  SELECT 1 FROM audit_archive_member m JOIN platform_audit p ON p.audit_attempt_id=m.attempt_id WHERE m.batch_id=#{id}
)
